// Managed by AMP - regenerated on every start. Put your own overrides in common_local.cfg.
set hub_listenTo "{{$HubPort}}"
set jsonp_listenPort "{{$HubStatusPort}}"

// Managed by AMP - regenerated on every start. Put your own overrides in common_local.cfg.
set shard_listenTo "{{$ShardPort}}"
set net_overrideDedicatedServerAddr "{{PublicAddress}}"

# Managed by AMP - regenerated on every start. Windows version of amp-settings.sh, see there for details.
$f = '{{$FullBaseDir}}cloud\data\default_platform_config.lua'
$begin = '-- >>> AMP managed settings'
$end = '-- <<< AMP managed settings'
if (-not (Test-Path $f)) { Write-Output "AMP settings: $f not found"; exit 1 }
$text = [IO.File]::ReadAllText($f)
$text = [regex]::Replace($text, '(?ms)^' + [regex]::Escape($begin) + '.*?^' + [regex]::Escape($end) + '[^\n]*\n', '')

# External MongoDB (see amp-settings.sh): db_mongoHosts in a marked block of common_local.cfg.
$c = '{{$FullBaseDir}}cloud\data\common_local.cfg'
if (Test-Path $c) {
    $ct = [regex]::Replace([IO.File]::ReadAllText($c), '(?ms)^// >>> AMP managed.*?^// <<< AMP managed[^\n]*\n', '')
    [IO.File]::WriteAllText($c, $ct)
}
if ('{{MongoMode}}' -eq 'external') {
    if (-not '{{MongoHosts}}') { Write-Output 'AMP settings: MongoDB is set to External but External MongoDB Hosts is empty. Aborting'; exit 1 }
    [IO.File]::AppendAllText($c, "// >>> AMP managed (rewritten on every start; put your own settings outside this block)`nset db_mongoHosts `"{{MongoHosts}}`"`n// <<< AMP managed`n")
    Write-Output 'AMP settings: using external MongoDB {{MongoHosts}}'
} elseif ('{{$MongoPort}}' -ne '27017') {
    # Bundled MongoDB on this instance's own port (so several instances can share one host).
    [IO.File]::AppendAllText($c, "// >>> AMP managed (rewritten on every start; put your own settings outside this block)`nset db_mongoHosts `"127.0.0.1:{{$MongoPort}}`"`n// <<< AMP managed`n")
}

# Battle pass (see amp-settings.sh): edited in place, disabled writes back the vanilla values.
$bpStart = '2023-06-09T05:00:00Z'
$bpTable = '{ {1,"2023-09-14T00:00:00Z"}, {2,"2023-09-14T00:00:00Z"}, {3,"2023-09-14T00:00:00Z"}}'
$bpUnlock = '2023-07-14T00:00:00Z'
# Dates in any common format (AMP stores e.g. "10/13/2026 00:00:00"), taken as UTC.
function Utc($v) {
    if (-not $v) { return '' }
    $d = [datetime]::MinValue
    $styles = [Globalization.DateTimeStyles]::AdjustToUniversal -bor [Globalization.DateTimeStyles]::AssumeUniversal
    if ([datetime]::TryParse($v, [Globalization.CultureInfo]::InvariantCulture, $styles, [ref]$d)) { return $d.ToString('yyyy-MM-ddTHH:mm:ssZ') }
    return $null
}
if ('{{BattlePassEnabled}}' -eq 'true') {
    $s = Utc '{{BattlePassStart}}'; $e = Utc '{{BattlePassEnd}}'
    if (-not $s) { Write-Output "AMP settings: Battle Pass Start '{{BattlePassStart}}' is not a date, battle pass left disabled" }
    elseif ($null -eq $e) { Write-Output "AMP settings: Battle Pass End '{{BattlePassEnd}}' is not a date, battle pass left disabled" }
    else {
        $bpStart = $s; $bpTable = '{ {1,"' + $e + '"}}'; $bpUnlock = $s
        Write-Output "AMP settings: battle pass active from $s $(if ($e) { "until $e" } else { 'with no end' })"
    }
}
$text = [regex]::Replace($text, '(?m)^(\s*local battlePassStart\s*=\s*)"[^"]*"', { param($m) $m.Groups[1].Value + '"' + $bpStart + '"' })
$text = [regex]::Replace($text, '(?m)^(\s*local battlePassEndTable\s*=\s*)\{.*\}( --)', { param($m) $m.Groups[1].Value + $bpTable + $m.Groups[2].Value })
$text = [regex]::Replace($text, '(?m)^(\s*cvars\.store_battlePassUnlockLvlBtnStart\s*=\s*)"[^"]*"', { param($m) $m.Groups[1].Value + '"' + $bpUnlock + '"' })

# Arena bots (see amp-settings.sh): bot count also in both arcade queue templates' "special" table.
$bots = if ([double]'{{ArenaBotsCount}}' -eq 6) { '' } else { ', botsCount = {{ArenaBotsCount}}' }
$text = [regex]::Replace($text, '(?m)^(\s*special = \{ arcade = 1)(, botsCount = \d+)?( \},)', { param($m) $m.Groups[1].Value + $bots + $m.Groups[3].Value })

# DLC packs in the shop (experimental, see amp-settings.sh): flags="15" on the Bundle_Arc_DLC_* store items.
$s = '{{$FullBaseDir}}cloud\data\store.xml'
if (Test-Path $s) {
    $st = [IO.File]::ReadAllText($s)
    $st = [regex]::Replace($st, '(?m)^(\s*<Item id="\d+")( flags="\d+")?(?=[^\n]*defName="Bundle_Arc_DLC_)', { param($m) $m.Groups[1].Value })
    if ('{{DlcPacksInShop}}' -eq 'true') {
        $st = [regex]::Replace($st, '(?m)^(\s*<Item id="\d+")(?=[^\n]*defName="Bundle_Arc_DLC_)', { param($m) $m.Groups[1].Value + ' flags="15"' })
        Write-Output 'AMP settings: DLC packs shown in the shop'
    }
    [IO.File]::WriteAllText($s, $st)
}

# Coop vs AI team size (experimental, see amp-settings.sh): N-1 allied and N enemy bots, sized for one player.
$coopN = [int][math]::Floor([double]'{{CoopTeamSize}}')
$coop = ''
if ($coopN -ge 2) {
    $coop = ", botsCount = $(2 * $coopN - 1), botsInTeam1 = $($coopN - 1)"
    Write-Output "AMP settings: coop vs AI sized for ${coopN}v${coopN} (botsCount $(2 * $coopN - 1), botsInTeam1 $($coopN - 1))"
}
$text = [regex]::Replace($text, '(coop_vs_ai = 1)(, botsCount = \d+, botsInTeam1 = \d+)?( \})', { param($m) $m.Groups[1].Value + $coop + $m.Groups[3].Value })

$block = [ordered]@{}
function Emit($svc, $cvar, $value) {
    if (-not $block.Contains($svc)) { $block[$svc] = '' }
    $block[$svc] += "`tcvars.$cvar = $value`r`n"
}
function Num($svc, $cvar, $value, $vanilla) {
    if ([double]$value -ne [double]$vanilla) { Emit $svc $cvar $value }
}
function Str($svc, $cvar, $value, $vanilla) {
    if ($value -ne $vanilla) { Emit $svc $cvar ('"' + $value + '"') }
}
function RankList($svc, $cvar, $value) {
    if ([double]$value -ne 1) { Emit $svc $cvar ('"' + ((1..18 | ForEach-Object { $value }) -join ',') + '"') }
}

Num 'ST_SHARD' 'credits_on_start' '{{NewAccountCredits}}' 0
Num 'ST_SHARD' 'gold_on_start' '{{StartingGold}}' 300
# premium_on_start is in hours (the game multiplies by 3600 into 32 bits, so it is capped at 20000 days)
Num 'ST_SHARD' 'premium_on_start' ([int]([math]::Min([double]'{{StartingPremiumDays}}', 20000) * 24)) 0
Num 'ST_SHARD' 'premiumTimeForAccountRank' ([int]([double]'{{PremiumHoursPerRank}}' * 3600)) 86400
if ('{{InfinitePremium}}' -eq 'true') { Str 'ST_SHARD' 'auth_infinitePremiumForRoles' 'gm;support;player' 'gm;support' }
RankList 'ST_MATCHMAKER' 'rate_exp' '{{XpMultiplier}}'
RankList 'ST_ZONE_INSTANCE' 'sv_expRate' '{{XpMultiplier}}'
RankList 'ST_MATCHMAKER' 'rate_cred' '{{CreditMultiplier}}'
foreach ($svc in 'ST_DEDICATED_SERVER', 'ST_ZONE_INSTANCE') {
    foreach ($mode in 'Pve', 'Pvp', 'Coop', 'Brawl') { Num $svc "sv_dailyWin${mode}ExpRewardCf" '{{FirstWinXpMultiplier}}' 3 }
}
Num 'ST_GAME_REWARD_DISPENCER' 'reward_bonusGoldForWinner' '{{BonusGoldWinner}}' 0
Num 'ST_GAME_REWARD_DISPENCER' 'reward_bonusGoldForLooser' '{{BonusGoldLoser}}' 0
Num 'ST_SHARD' 'sv_tokenCreditsDailyLimit' '{{TokenDailyLimit}}' 1000
Num 'ST_GAME_REWARD_DISPENCER' 'sv_tokenCreditsDailyLimit' '{{TokenDailyLimit}}' 1000
Num 'ST_SHARD' 'store_vesselPriceMod' '{{ShipPriceMultiplier}}' 1
Num 'ST_SHARD' 'store_modulePriceMod' '{{ModulePriceMultiplier}}' 1
Num 'ST_SHARD' 'store_munitionPriceMod' '{{AmmoPriceMultiplier}}' 1
Num 'ST_DEDICATED_SERVER' 'sv_afkCheckDuration' '{{AfkKickSeconds}}' 120
Num 'ST_ZONE_INSTANCE' 'sv_resurrectionCreditsPrice' '{{ResurrectionCost}}' 100000
Num 'ST_LOAD_BALANCER' 'lb_limitPlayersOnShardTo' '{{$MaxUsers}}' 800

if ($block.Count -gt 0) {
    $text += "$begin (rewritten by AMP on every start)`r`n"
    foreach ($svc in $block.Keys) { $text += "if( service_type == `"$svc`" ) then`r`n" + $block[$svc] + "end`r`n" }
    $text += "$end`r`n"
    Write-Output 'AMP settings written to default_platform_config.lua'
} else {
    Write-Output 'AMP settings: block settings all vanilla, no AMP block written'
}
[IO.File]::WriteAllText($f, $text)
